sp_SalvarCertificadoA1	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_SalvarCertificadoA1`(\n\n    IN p_idEmpresa INT, IN p_certificadoA1 LONGBLOB,\n\n    IN p_senhaCertificado VARCHAR(100), IN p_dthVencimento DATE\n\n)\nBEGIN\n\n    UPDATE EmpresaConfigFiscal\n\n    SET certificadoA1=p_certificadoA1, senhaCertificado=p_senhaCertificado,\n\n        dthVencCertificado=p_dthVencimento\n\n    WHERE idEmpresa=p_idEmpresa;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
